 const originals=plan.members as BuildingComponent[];if(originals.some(c=>!own(c)||!exact(c,own(c)!)))return current;
 const p=progressivePaintData(originals),f=facadePaintData(originals),result=applyS036NorthCoface(originals,p,f,plan);if(!result.enabled)return current;
 let off=0;for(const c of originals){const n=count(c),e=(OLD as Record<string,{paint:number[];frames:number[]}>)[c.partId];if(!eq(p.subarray(off*4,(off+n)*4),e.paint)||!eq(f.subarray(off*5,(off+n)*5),e.frames))return current;off+=n;}
 off=0;for(const c of cs){const original=sourceByDisplay.get(c)??c;if(originals.includes(original)){const e=(OLD as Record<string,{paint:number[];frames:number[]}>)[c.partId];paint.set(e.paint,off*4);frames.set(e.frames,off*5);}off+=count(c);}
